from collections import Counter
from itertools import combinations, product
import heapq


def _build_interval(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for subset in combinations(jobs, k):
            ids = [job["id"] for job in subset]
            id_set = set(ids)
            if not mandatory.issubset(id_set) or blocked.intersection(id_set):
                continue

            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active_ends = []
            compatible = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while active_ends and active_ends[0] <= job["start"]:
                    heapq.heappop(active_ends)
                heapq.heappush(active_ends, job["end"])
                if len(active_ends) > capacity:
                    compatible = False
                    break
            if not compatible:
                continue

            selected = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (selected < best_ids if tie == "smallest" else selected > best_ids))):
                best_value, best_ids = value, selected

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        rows_by_name = {name: {row["version"]: row for row in rows}
                        for name, rows in packages.items()}
        domains = []
        for name in names:
            versions = sorted(rows_by_name[name])
            versions = [v for v in versions if v not in blocked.get(name, [])
                        and (name not in pins or pins[name] == v)]
            domains.append([-1] + versions)

        best = None
        for vector in product(*domains):
            assigned = dict(zip(names, vector))
            installed = {name: version for name, version in assigned.items() if version != -1}
            if any(name not in installed or not low <= installed[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {}
            constraints_ok = True
            for name, version in installed.items():
                row = rows_by_name[name][version]
                active = [dep for dep in row.get("deps", [])
                          if not dep.get("feature") or dep.get("feature") in features]
                edges[name] = []
                for dep in active:
                    other = dep["name"]
                    edges[name].append(other)
                    if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                        constraints_ok = False
                        break
                if not constraints_ok:
                    break
            if not constraints_ok:
                continue

            closure = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in closure:
                    continue
                if name not in installed:
                    constraints_ok = False
                    break
                closure.add(name)
                stack.extend(edges.get(name, []))
            if not constraints_ok or closure != set(installed):
                continue

            state, cyclic = {}, False
            def visit(name):
                nonlocal cyclic
                if state.get(name) == 1:
                    cyclic = True
                    return
                if state.get(name) == 2:
                    return
                state[name] = 1
                for other in edges.get(name, []):
                    visit(other)
                state[name] = 2
            for name in installed:
                visit(name)
            if cyclic:
                continue

            if best is None or vector < best:
                best = vector

        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": {name: version for name, version in zip(names, best)
                              if version != -1}}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and time <= data["deadline"]:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(depart + edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((depart + duration, remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                for arrival, coupons_left in options:
                    if arrival > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, coupons_left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, coupons_left))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_interval(1, "smallest"),
    "component_02": _build_interval(2, "smallest"),
    "component_03": _build_interval(1, "largest"),
    "component_04": _build_interval(2, "largest"),
    "component_05": _build_interval(1, "smallest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
